WITH ev AS (
    SELECT e.event_id,
           e.status,
           AVG(b.remaining) AS avg_remaining,
           AVG((b.spent - b.amount) * 1.0 / b.amount) AS avg_ratio
    FROM budget b
    JOIN event e ON b.link_to_event = e.event_id
    GROUP BY e.event_id, e.status
),
overall AS (
    SELECT AVG(avg_remaining) AS overall_avg FROM ev
)
SELECT ev.status,
       AVG(ev.avg_remaining) / (SELECT overall_avg FROM overall) AS ratio
FROM ev
GROUP BY ev.status;
SELECT AVG(avg_remaining) AS overall_avg_remaining
FROM (
    SELECT event_status, AVG(remaining) AS avg_remaining
    FROM budget
    GROUP BY event_status
);
SELECT status, COUNT(*) FROM event GROUP BY status;
SELECT event_status, COUNT(DISTINCT link_to_event) FROM budget GROUP BY event_status;
SELECT AVG((spent - amount) * 1.0 / amount) FROM budget WHERE remaining < 0 AND amount <> 0;
